WITH remaining_keys AS (SELECT level, manager_id FROM employees EXCEPT SELECT level, manager_id FROM employees WHERE is_remote), reconciled AS (SELECT s.* FROM employees s INNER JOIN remaining_keys k ON s.level = k.level AND s.manager_id = k.manager_id), with_dims AS (SELECT e.*, d.dept_name, d.location FROM reconciled e LEFT JOIN departments d ON e.dept_id = d.id), enriched AS (SELECT *, CUME_DIST() OVER (PARTITION BY level ORDER BY salary DESC) AS salary_cume_dist, CUME_DIST() OVER (ORDER BY salary ASC) AS salary_cume_dist_2 FROM with_dims), with_windows AS (SELECT id, email, dept_id, salary, hire_date, dept_name, location, salary_cume_dist_2, AVG(salary_cume_dist) OVER (PARTITION BY dept_id) AS dept_id_avg_salary_cume_dist, PERCENT_RANK() OVER (PARTITION BY dept_id, manager_id ORDER BY salary ASC) AS salary_percent_rank, MAX(salary_cume_dist_2) OVER (PARTITION BY location) AS location_max_salary_cume_dist_2, DENSE_RANK() OVER (ORDER BY salary_cume_dist DESC NULLS FIRST) AS salary_cume_dist_dense_rank FROM enriched), metrics AS (SELECT *, PERCENT_RANK() OVER (PARTITION BY location ORDER BY salary ASC) AS salary_percent_rank_2, RANK() OVER (PARTITION BY location ORDER BY salary_percent_rank DESC) AS salary_percent_rank_rank, PERCENT_RANK() OVER w_hist AS salary_cume_dist_2_percent_rank FROM with_windows WHERE dept_name = 'Legal' WINDOW w_hist AS (ORDER BY salary_cume_dist_2 DESC NULLS FIRST)) SELECT dept_name, metric_name, reading FROM (SELECT dept_name, salary_cume_dist_2, salary_cume_dist_2_percent_rank, salary_percent_rank FROM metrics) src UNPIVOT (reading FOR metric_name IN (salary_cume_dist_2, salary_cume_dist_2_percent_rank, salary_percent_rank));
